-- Load monitor settings generated by nwg-displays into the active Lua config.
-- This file intentionally contains no fixed output name, mode, position, or scale.

local config_home = os.getenv("XDG_CONFIG_HOME") or ((os.getenv("HOME") or "") .. "/.config")
local monitors_conf = config_home .. "/hypr/monitors.conf"

local function trim(value)
    return (value:gsub("^%s+", ""):gsub("%s+$", ""))
end

local function split_csv(value)
    local fields = {}
    local start = 1
    while true do
        local comma = value:find(",", start, true)
        if not comma then
            table.insert(fields, trim(value:sub(start)))
            break
        end
        table.insert(fields, trim(value:sub(start, comma - 1)))
        start = comma + 1
    end
    return fields
end

local file = io.open(monitors_conf, "r")
if file then
    local specs = {}
    local order = {}

    local function get_spec(output)
        if not specs[output] then
            specs[output] = { output = output }
            table.insert(order, output)
        end
        return specs[output]
    end

    for line in file:lines() do
        if not line:match("^%s*#") then
            local value = line:match("^%s*monitor%s*=%s*(.-)%s*$")
            if value then
                local fields = split_csv(value)
                local output = fields[1] or ""
                local action = fields[2]
                local spec = get_spec(output)

                if action == "disable" then
                    specs[output] = { output = output, disabled = true }
                elseif action == "transform" then
                    spec.transform = tonumber(fields[3]) or fields[3]
                elseif action and action ~= "" then
                    spec.disabled = nil
                    spec.mode = action
                    spec.position = fields[3] or "auto"
                    local raw_scale = tonumber(fields[4])
                    if raw_scale then
                        -- nwg-displays may serialize 1.5 as 1.5000000000000004.
                        spec.scale = math.floor(raw_scale * 1000 + 0.5) / 1000
                    else
                        spec.scale = fields[4] or 1
                    end

                    local index = 5
                    while index <= #fields do
                        local key = fields[index]
                        local item = fields[index + 1]
                        if key == "mirror" then
                            spec.mirror = item
                        elseif key == "bitdepth" then
                            spec.bitdepth = tonumber(item) or item
                        end
                        index = index + 2
                    end
                end
            end
        end
    end
    file:close()

    for _, output in ipairs(order) do
        hl.monitor(specs[output])
    end
end
